public sealed class OrderFacade(AppDbContext db, PricingService pricing, InventoryService inv)
{
    public async Task<OrderId> PlaceOrderAsync(PlaceOrderRequest req, CancellationToken ct)
    {
        await using var tx = await db.Database.BeginTransactionAsync(ct);  // unit of work
        inv.Reserve(req.Sku, req.Quantity);
        var order = db.Orders.Add(new Order(req.CustomerId, pricing.Quote(req.Sku, req.Quantity)));
        await db.SaveChangesAsync(ct);
        await tx.CommitAsync(ct);
        return order.Entity.Id;
    }
}
